def brute(a):
    n=len(a)
    best=0
    # DP matching maximum on sorted list
    # simple recursion choose pairs
    from functools import lru_cache
    @lru_cache(None)
    def f(mask):
        if mask==0: return 0
        i=(mask & -mask).bit_length()-1
        best=f(mask^(1<<i))
        m=mask^(1<<i)
        j=i+1
        while j<n:
            if (m>>j)&1 and 2*a[i]<=a[j]:
                best=max(best,1+f(m^(1<<j)))
            j+=1
        return best
    return f((1<<n)-1)

